import React, { useState, useCallback, useEffect, useMemo } from "react";
import { useSearchParams, useLocation, useNavigate } from "react-router-dom";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import AppHeader from "@/components/AppHeader";
import AuthDialog from "@/components/AuthDialog";
import JobSidebar from "@/components/JobSidebar";
import JobDetailView from "@/components/JobDetailView";
import JobsOverviewCard from "@/components/JobsOverviewCard";
import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
import { format } from "date-fns";
import { toast } from "sonner";
import OnboardingWizard from "@/components/OnboardingWizard";

export interface PastJob {
  id: string;
  title: string | null;
  job_description: string;
  status: string;
  created_at: string;
  resume_count: number;
  jd_analysis_json: any;
  dynamic_weights_json: Record<string, number> | null;
  inbox_email: string | null;
}

export interface Result {
  id: string;
  resume_id: string;
  overall_score: number;
  missing_skills: string[];
  summary: string | null;
  interview_questions: any;
  filename: string;
  file_path: string | null;
  candidate_name: string | null;
  candidate_email?: string | null;
  candidate_phone?: string | null;
  candidate_location?: string | null;
  // Dynamic scoring fields
  hard_fit?: boolean;
  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
  confidence?: number;
  strengths_json?: string[];
  gaps_json?: string[];
  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
  matched_must_haves?: string[];
  missing_must_haves?: string[];
  scoring_version?: string;
  pending?: boolean;
  parsed_json?: any;
  assigned_to?: string | null;
}

export interface ExistingResume {
  id: string;
  filename: string;
  file_path: string | null;
  candidate_name: string | null;
  created_at: string;
}

type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";

const ONBOARDING_KEY = "rankora_onboarding_done";

const Index = () => {
  const { user, profile } = useAuth();
  const [searchParams, setSearchParams] = useSearchParams();
  const location = useLocation();
  const navigate = useNavigate();

  // Show onboarding wizard for first-time users
  const [showOnboarding, setShowOnboarding] = useState(() => {
    if (typeof window === "undefined") return false;
    return !localStorage.getItem(ONBOARDING_KEY);
  });

  const completeOnboarding = useCallback(() => {
    localStorage.setItem(ONBOARDING_KEY, "1");
    setShowOnboarding(false);
  }, []);

  const queryClient = useQueryClient();

  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
    queryKey: ["pastJobs", user?.id],
    queryFn: async () => {
      const { data: jobs } = await supabase
        .from("jobs")
        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
        .eq("user_id", user!.id)
        .order("created_at", { ascending: false })
        .limit(50);
      if (!jobs) return [];
      return jobs.map((j: any) => ({
        id: j.id,
        title: j.title,
        job_description: j.job_description,
        status: j.status,
        created_at: j.created_at,
        resume_count: j.resumes?.[0]?.count ?? 0,
        jd_analysis_json: j.jd_analysis_json,
        dynamic_weights_json: j.dynamic_weights_json,
        inbox_email: j.inbox_email ?? null,
      })) as PastJob[];
    },
    enabled: !!user,
    staleTime: 2 * 60 * 1000,
  });

  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
  const [results, setResults] = useState<Result[]>([]);
  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
  const [authOpen, setAuthOpen] = useState(false);

  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);

  // Sync view with route path
  useEffect(() => {
    if (location.pathname === "/jobs") {
      setView("my-jobs");
      setSelectedJobId(null);
    }
  }, [location.pathname]);

  // Handle URL params for deep linking
  useEffect(() => {
    const jobParam = searchParams.get("job");
    const newParam = searchParams.get("new");

    if (jobParam && user) {
      loadJobData(jobParam);
      setSearchParams({}, { replace: true });
    } else if (newParam && user) {
      handleNewJob();
      setSearchParams({}, { replace: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams, user]);

  const loadJobData = async (jobId: string) => {
    setSelectedJobId(jobId);
    setView("job-detail");
    try {
      // Single query for all resume data (was 2 separate queries)
      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at, parsed_json")
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });

      const resumeData = allResumes ?? [];
      setExistingResumes(resumeData.map((r) => ({
        id: r.id, filename: r.filename, file_path: r.file_path,
        candidate_name: r.candidate_name, created_at: r.created_at,
      })));

      if (resumeData.length === 0) {
        setResults([]);
        return;
      }

      const resumeIds = resumeData.map((r) => r.id);
      const { data: resultData } = await supabase
        .from("results")
        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
        .in("resume_id", resumeIds);

      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
        const resume = resumeMap.get(r.resume_id);
        const parsed = resume?.parsed_json as any;
        return {
          ...r,
          overall_score: r.overall_score ?? 0,
          missing_skills: r.missing_skills ?? [],
          filename: resume?.filename ?? "Unknown",
          file_path: resume?.file_path ?? null,
          candidate_name: resume?.candidate_name ?? null,
          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
          parsed_json: resume?.parsed_json ?? null,
        };
      });
      // Deduplicate by resume_id — keep highest scoring result per resume
      const deduped = new Map<string, Result>();
      for (const r of allMerged) {
        const existing = deduped.get(r.resume_id);
        if (!existing || r.overall_score > existing.overall_score) {
          deduped.set(r.resume_id, r);
        }
      }
      const merged = Array.from(deduped.values());
      merged.sort((a, b) => b.overall_score - a.overall_score);
      setResults(merged);
    } catch (err) {
      toast.error("Failed to load job data");
    }
  };

  const handleNewJob = () => {
    setSelectedJobId(null);
    setView("new-job");
    setResults([]);
    setExistingResumes([]);
  };

  const handleGoToDashboard = () => {
    setSelectedJobId(null);
    setView("dashboard");
    setResults([]);
    setExistingResumes([]);
    navigate("/", { replace: true });
  };

  const handleGoToMyJobs = () => {
    setSelectedJobId(null);
    setView("my-jobs");
    setResults([]);
    setExistingResumes([]);
    navigate("/jobs", { replace: true });
  };

  const handleJobCreated = (job: PastJob) => {
    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) => [job, ...(prev ?? [])]);
    setSelectedJobId(job.id);
    loadJobData(job.id);
  };

  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
      (prev ?? []).map((j) => (j.id === jobId ? { ...j, ...updates } : j))
    );
  };

  const handleDeleteJobs = async (jobIds: string[]) => {
    try {
      const { error } = await supabase.from("jobs").delete().in("id", jobIds);
      if (error) throw error;
      queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
        (prev ?? []).filter((j) => !jobIds.includes(j.id))
      );
    } catch (err: any) {
      toast.error(err?.message || "Failed to delete jobs");
    }
  };

  const requireAuth = useCallback(() => {
    if (!user) { setAuthOpen(true); return true; }
    return false;
  }, [user]);

  return (
    <SidebarProvider className="h-svh overflow-hidden">
      <JobSidebar
        showDashboard={view === "dashboard"}
        showMyJobs={view === "my-jobs" || view === "job-detail"}
        onNewJob={handleNewJob}
        onDashboard={handleGoToDashboard}
        onMyJobs={handleGoToMyJobs}
        onAuthRequired={() => setAuthOpen(true)}
        isAuthenticated={!!user}
      />

      <SidebarInset className="h-svh overflow-hidden bg-sidebar p-2 pl-0">
        <div className="h-full flex flex-col rounded-xl border bg-background overflow-hidden">
        <AppHeader />
        <div className="flex items-center h-10 px-4 md:hidden">
          <SidebarTrigger />
          <span className="ml-2 text-sm font-medium text-muted-foreground">Menu</span>
        </div>
        <div className="flex-1 overflow-y-auto">

        {/* Dashboard view */}
        {view === "dashboard" && user ? (
          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
            {/* Hero Section — Greeting + Create Button */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div>
                <h1 className="text-2xl font-bold text-foreground">
                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                  Here's an overview of your hiring activity and insights.
                </p>
              </div>
              <Button className="gap-2" onClick={handleNewJob}>
                <Plus className="h-4 w-4" /> Create Job
              </Button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              {[
                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
              ].map((s) => (
                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
                  <CardContent className="px-5 py-4 flex items-center gap-4">
                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
                      <s.icon className="h-5 w-5" />
                    </div>
                    <div>
                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>

            {/* Recent Jobs */}
            {pastJobs.length > 0 && (
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
                    View All Jobs →
                  </button>
                </div>
                <div className="grid gap-3">
                  {pastJobs.slice(0, 5).map((job) => (
                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
                        <div className="flex items-center gap-3 min-w-0">
                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                            <Briefcase className="h-4 w-4 text-primary" />
                          </div>
                          <div className="min-w-0">
                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
                            <p className="text-xs text-muted-foreground mt-0.5">
                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
                            </p>
                          </div>
                        </div>
                        <div className="flex items-center gap-3 shrink-0">
                          <Badge
                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
                            className="text-xs"
                          >
                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
                          </Badge>
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            )}

            {/* Getting started guide — show only for new users */}
            {pastJobs.length === 0 && !loadingPastJobs && (
              <Card className="border border-border/60 shadow-sm">
                <CardContent className="px-5 py-4 space-y-3">
                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
                  <div className="space-y-2.5">
                    {[
                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
                    ].map((item) => (
                      <div key={item.step} className="flex items-start gap-3 text-sm">
                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
                        <span className="text-muted-foreground">{item.text}</span>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </main>
        ) : view === "my-jobs" && user ? (
          /* My Jobs view — full management */
          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
              <div className="space-y-1">
                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
                <p className="text-sm text-muted-foreground">Manage all your job postings.</p>
              </div>
              <Button className="gap-2 shrink-0" onClick={handleNewJob}>
                <Plus className="h-4 w-4" /> Create Job
              </Button>
            </div>
            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
          </main>
        ) : (
          <JobDetailView
            selectedJobId={selectedJobId}
            selectedJob={selectedJob}
            results={results}
            setResults={setResults}
            existingResumes={existingResumes}
            setExistingResumes={setExistingResumes}
            onJobCreated={handleJobCreated}
            onAuthRequired={() => setAuthOpen(true)}
            isAuthenticated={!!user}
            pastJobs={pastJobs}
            onJobUpdated={handleJobUpdated}
            onBack={handleGoToMyJobs}
          />
        )}
        </div>
        </div>
      </SidebarInset>

      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />

      {user && showOnboarding && (
        <OnboardingWizard
          open={showOnboarding}
          onComplete={completeOnboarding}
          onCreateJob={() => { completeOnboarding(); handleNewJob(); }}
          onGoToTeam={() => { completeOnboarding(); navigate("/team"); }}
          userName={user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0] || "there"}
        />
      )}
    </SidebarProvider>
  );
};

export default Index;
