import { useState, useEffect, useRef } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import {
  Camera,
  Trash2,
  Globe,
  Twitter,
  Linkedin,
  Github,
  Briefcase,
  MapPin,
  Building2,
  Loader2,
  Shield,
  Eye,
  EyeOff,
} from "lucide-react";

// ─── helpers ──────────────────────────────────────────────────────────────────

function getInitials(email?: string | null, fullName?: string | null): string {
  if (fullName) {
    const parts = fullName.trim().split(/\s+/);
    if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
    return parts[0][0]?.toUpperCase() ?? "?";
  }
  if (!email) return "?";
  const local = email.split("@")[0];
  const parts = local.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return local[0]?.toUpperCase() ?? "?";
}

// ─── types ────────────────────────────────────────────────────────────────────

interface ProfileFields {
  full_name: string | null;
  username: string | null;
  bio: string | null;
  avatar_url: string | null;
  job_title: string | null;
  company: string | null;
  location: string | null;
  website: string | null;
  twitter: string | null;
  linkedin: string | null;
  github: string | null;
}

interface FormState {
  full_name: string;
  username: string;
  bio: string;
  avatar_url: string;
  job_title: string;
  company: string;
  location: string;
  website: string;
  twitter: string;
  linkedin: string;
  github: string;
}

const EMPTY: FormState = {
  full_name: "", username: "", bio: "", avatar_url: "",
  job_title: "", company: "", location: "",
  website: "", twitter: "", linkedin: "", github: "",
};

function toForm(p: ProfileFields): FormState {
  return Object.fromEntries(
    Object.entries(EMPTY).map(([k]) => [k, (p as Record<string, string | null>)[k] ?? ""])
  ) as FormState;
}

// ─── prefix input ─────────────────────────────────────────────────────────────

function PrefixInput({
  prefix, value, onChange, placeholder,
}: {
  prefix: string;
  value: string;
  onChange: (v: string) => void;
  placeholder: string;
}) {
  return (
    <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:border-ring overflow-hidden transition-shadow">
      <span className="flex items-center px-3 text-xs text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
        {prefix}
      </span>
      <input
        className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground min-w-0"
        placeholder={placeholder}
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
    </div>
  );
}

// ─── component ────────────────────────────────────────────────────────────────

const Profile = () => {
  const { user, refreshProfile } = useAuth();
  const queryClient = useQueryClient();
  const fileRef = useRef<HTMLInputElement>(null);

  const [form, setForm] = useState<FormState>(EMPTY);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);

  // Password
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [savingPw, setSavingPw] = useState(false);
  const [showPw, setShowPw] = useState(false);
  const pwMatch = newPassword && confirmPassword && newPassword === confirmPassword;
  const pwMismatch = confirmPassword.length > 0 && newPassword !== confirmPassword;

  // ── fetch profile fields ────────────────────────────────────────────────
  const { data: loaded, isLoading } = useQuery<ProfileFields>({
    queryKey: ["profileFull", user?.id],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("profiles")
        .select("full_name, username, bio, avatar_url, job_title, company, location, website, twitter, linkedin, github")
        .eq("user_id", user!.id)
        .single();
      if (error) throw error;
      return data as ProfileFields;
    },
    enabled: !!user,
    staleTime: 5 * 60 * 1000,
  });

  useEffect(() => {
    if (loaded) setForm(toForm(loaded));
  }, [loaded]);

  const set = (key: keyof FormState) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
    setForm((f) => ({ ...f, [key]: e.target.value }));

  // ── avatar ──────────────────────────────────────────────────────────────
  const handleAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;
    if (file.size > 5 * 1024 * 1024) { toast.error("Max 5 MB"); return; }
    if (!file.type.startsWith("image/")) { toast.error("Images only"); return; }

    setUploading(true);
    try {
      const ext = file.name.split(".").pop();
      const path = `${user.id}/avatar.${ext}`;
      const { error } = await supabase.storage.from("avatars").upload(path, file, { upsert: true, contentType: file.type });
      if (error) throw error;
      const { data: u } = supabase.storage.from("avatars").getPublicUrl(path);
      const url = u.publicUrl + `?t=${Date.now()}`;
      await (supabase as any).from("profiles").update({ avatar_url: url }).eq("user_id", user.id);
      setForm((f) => ({ ...f, avatar_url: url }));
      queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
      toast.success("Photo updated");
    } catch { toast.error("Upload failed"); }
    finally { setUploading(false); if (fileRef.current) fileRef.current.value = ""; }
  };

  const removeAvatar = async () => {
    if (!user) return;
    try { await supabase.storage.from("avatars").remove([`${user.id}/avatar.jpg`, `${user.id}/avatar.png`, `${user.id}/avatar.webp`]); } catch {}
    setForm((f) => ({ ...f, avatar_url: "" }));
    await (supabase as any).from("profiles").update({ avatar_url: null }).eq("user_id", user.id);
    queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
    toast.success("Photo removed");
  };

  // ── save / cancel ───────────────────────────────────────────────────────
  const handleSave = async () => {
    if (!user) return;
    setSaving(true);
    try {
      const payload = Object.fromEntries(
        Object.entries(form).map(([k, v]) => [k, v.trim() || null])
      );
      const { error } = await (supabase as any).from("profiles").update(payload).eq("user_id", user.id);
      if (error) throw error;
      await refreshProfile();
      queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
