// ── new task dialog ───────────────────────────────────────────────────────────

interface NewTaskDialogProps {
  members: { user_id: string; email?: string }[];
  isCreating: boolean;
  onSubmit: (values: {
    title: string;
    description?: string;
    assigned_to?: string;
    priority: TaskPriority;
    due_date?: string;
  }) => void;
}

function NewTaskDialog({ members, isCreating, onSubmit }: NewTaskDialogProps) {
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [assignedTo, setAssignedTo] = useState<string>("__none__");
  const [priority, setPriority] = useState<TaskPriority>("medium");
  const [dueDate, setDueDate] = useState("");

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({
      title: title.trim(),
      description: description.trim() || undefined,
      assigned_to: assignedTo !== "__none__" ? assignedTo : undefined,
      priority,
      due_date: dueDate || undefined,
    });
    // reset
    setTitle("");
    setDescription("");
    setAssignedTo("__none__");
    setPriority("medium");
    setDueDate("");
    setOpen(false);
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" className="gap-1.5">
          <Plus className="h-4 w-4" />
          New Task
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Create task</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 pt-2">
          <div className="space-y-1.5">
            <label className="text-sm font-medium" htmlFor="task-title">
              Title <span className="text-destructive">*</span>
            </label>
            <Input
              id="task-title"
              placeholder="e.g. Review resumes for frontend role"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
              autoFocus
            />
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium" htmlFor="task-desc">
              Description
            </label>
            <Textarea
              id="task-desc"
              placeholder="Optional notes or context…"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              className="resize-none"
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <label className="text-sm font-medium">Assign to</label>
              <Select value={assignedTo} onValueChange={setAssignedTo}>
                <SelectTrigger>
                  <SelectValue placeholder="Unassigned" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">Unassigned</SelectItem>
                  {members.map((m) => (
                    <SelectItem key={m.user_id} value={m.user_id}>
                      {m.email ?? m.user_id.slice(0, 8) + "…"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium">Priority</label>
              <Select
                value={priority}
                onValueChange={(v) => setPriority(v as TaskPriority)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-medium" htmlFor="task-due">
              Due date
            </label>
            <Input
              id="task-due"
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
            />
          </div>

          <div className="flex justify-end gap-2 pt-1">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={isCreating}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isCreating || !title.trim()}>
              {isCreating ? (
                <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
              ) : null}
              Create
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

// ── main page ─────────────────────────────────────────────────────────────────

const Tasks = () => {
  const { user, isAdmin } = useAuth();
  const { team, members } = useTeam();
  const teamId = team?.id ?? null;
  const { tasks, isLoading, error, createTask, updateTask, deleteTask } =
    useTasks(teamId);

  const [deletingId, setDeletingId] = useState<string | null>(null);

  const today = new Date();
  const threeDaysFromNow = addDays(today, 3);

  const overdueTasks = tasks.filter(
    (t) =>
      t.status !== "done" &&
      t.due_date &&
      isBefore(parseISO(t.due_date), today)
  );
  const dueSoonTasks = tasks.filter(
    (t) =>
      t.status !== "done" &&
      t.due_date &&
      !isBefore(parseISO(t.due_date), today) &&
      isBefore(parseISO(t.due_date), threeDaysFromNow)
  );
  const upcomingTasks = tasks.filter(
    (t) =>
      t.status !== "done" &&
      t.due_date &&
      !isBefore(parseISO(t.due_date), threeDaysFromNow)
  );
  const noDueDateTasks = tasks.filter(
    (t) => t.status !== "done" && !t.due_date
  );
  const completedTasks = tasks.filter((t) => t.status === "done");

  async function handleToggle(task: Task) {
    const newStatus = task.status === "done" ? "todo" : "done";
    try {
      await updateTask.mutateAsync({ id: task.id, status: newStatus });
    } catch {
      toast.error("Failed to update task");
    }
  }

  async function handleDelete(id: string) {
    setDeletingId(id);
    try {
      await deleteTask.mutateAsync(id);
      toast.success("Task deleted");
    } catch {
      toast.error("Failed to delete task");
    } finally {
      setDeletingId(null);
    }
  }

  async function handleCreate(values: {
    title: string;
    description?: string;
    assigned_to?: string;
    priority: TaskPriority;
    due_date?: string;
  }) {
    try {
      await createTask.mutateAsync(values);
      toast.success("Task created");
    } catch {
      toast.error("Failed to create task");
    }
  }

  const sectionProps = {
    members,
    currentUserId: user?.id ?? "",
    isAdmin: !!isAdmin,
    onToggle: handleToggle,
    onDelete: handleDelete,
    deletingId,
  };

  const hasActiveTasks =
    overdueTasks.length +
      dueSoonTasks.length +
      upcomingTasks.length +
      noDueDateTasks.length >
    0;

  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
        {/* Page header */}
        <div className="flex items-center justify-between mb-1">
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold text-foreground">
              My Tasks
            </h1>
            {overdueTasks.length > 0 && (
              <Badge className="bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 border-0 text-xs">
                {overdueTasks.length} overdue
              </Badge>
            )}
            {dueSoonTasks.length > 0 && (
              <Badge className="bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-0 text-xs">
                {dueSoonTasks.length} due soon
              </Badge>
            )}
          </div>
          <NewTaskDialog
            members={members}
            isCreating={createTask.isPending}
            onSubmit={handleCreate}
          />
        </div>
        <p className="text-sm text-muted-foreground mb-6">
          Track action items and follow-ups across your team.
        </p>

        {/* Loading */}
        {isLoading && (
          <Card className="border border-border/60 shadow-sm">
            <CardContent className="py-3">
              <TasksSkeleton />
            </CardContent>
          </Card>
        )}

        {/* Error state */}
        {!isLoading && error && (
          <Card className="border-destructive/50">
            <CardContent className="py-8 text-center">
              <AlertCircle className="h-8 w-8 text-destructive mx-auto mb-2" />
              <p className="text-sm text-muted-foreground">Failed to load data. Please refresh the page.</p>
            </CardContent>
          </Card>
        )}

        {/* No team state */}
        {!isLoading && !teamId && (
          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <CheckSquare className="h-7 w-7 text-muted-foreground/50" />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">No team yet</p>
              <p className="text-sm text-muted-foreground max-w-xs">
                Create or join a team to start managing tasks collaboratively.
              </p>
            </div>
          </div>
        )}

        {/* Empty state */}
        {!isLoading && teamId && tasks.length === 0 && (
          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <CheckSquare className="h-7 w-7 text-muted-foreground/50" />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">No tasks yet</p>
              <p className="text-sm text-muted-foreground max-w-xs">
                Create your first task to track action items and follow-ups.
              </p>
            </div>
            <NewTaskDialog
              members={members}
              isCreating={createTask.isPending}
              onSubmit={handleCreate}
            />
          </div>
        )}

        {/* Task sections */}
        {!isLoading && teamId && (hasActiveTasks || completedTasks.length > 0) && (
          <div className="space-y-5">
            {overdueTasks.length > 0 && (
              <Card className="border border-border/60 shadow-sm">
                <CardContent className="py-3">
                  <TaskSection
                    title="Overdue"
                    tasks={overdueTasks}
                    variant="destructive"
                    icon={<AlertTriangle className="h-3.5 w-3.5 text-red-500 shrink-0" />}
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}

            {dueSoonTasks.length > 0 && (
              <Card className="border border-border/60 shadow-sm">
                <CardContent className="py-3">
                  <TaskSection
                    title="Due Soon"
                    tasks={dueSoonTasks}
                    variant="warning"
                    icon={<Clock className="h-3.5 w-3.5 text-amber-500 shrink-0" />}
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}

            {upcomingTasks.length > 0 && (
              <Card className="border border-border/60 shadow-sm">
                <CardContent className="py-3">
                  <TaskSection
                    title="Upcoming"
                    tasks={upcomingTasks}
                    icon={<Calendar className="h-3.5 w-3.5 text-muted-foreground shrink-0" />}
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}

            {noDueDateTasks.length > 0 && (
              <Card className="border border-border/60 shadow-sm">
                <CardContent className="py-3">
                  <TaskSection
                    title="No Due Date"
                    tasks={noDueDateTasks}
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}

            {completedTasks.length > 0 && (
              <Card className="border border-border/60 shadow-sm">
                <CardContent className="py-3">
                  <TaskSection
                    title="Completed"
                    tasks={completedTasks}
                    collapsed
                    {...sectionProps}
                  />
                </CardContent>
              </Card>
            )}
          </div>
        )}
      </main>
    </SidebarLayout>
  );
};

export default Tasks;
