/** Renders HTML embed code and executes any <script> tags within it */
function EmbedRenderer({ html }: { html: string }) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    // Sanitize embed HTML — allow iframes and external scripts for booking widgets
    const sanitized = DOMPurify.sanitize(html, {
      ADD_TAGS: ["script", "iframe"],
      ADD_ATTR: ["src", "async", "defer", "allow", "allowfullscreen", "frameborder", "scrolling"],
      FORCE_BODY: true,
    });

    const temp = document.createElement("div");
    temp.innerHTML = sanitized;

    el.innerHTML = "";
    const scripts: HTMLScriptElement[] = [];
    Array.from(temp.childNodes).forEach((node) => {
      if (node instanceof HTMLScriptElement) {
        scripts.push(node);
      } else {
        el.appendChild(node.cloneNode(true));
      }
    });

    // Only execute scripts with external src — strip inline scripts for safety
    scripts.forEach((orig) => {
      if (orig.src) {
        const script = document.createElement("script");
        script.src = orig.src;
        script.async = orig.async;
        el.appendChild(script);
      }
    });

    return () => {
      el.innerHTML = "";
    };
  }, [html]);

  return (
    <div
      ref={containerRef}
      className="w-full min-h-[700px] [&>iframe]:w-full [&>iframe]:min-h-[700px] [&>iframe]:border-0"
    />
  );
}

