import { useNavigate, useSearchParams } from "react-router-dom";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Zap } from "lucide-react";
import { toast } from "sonner";
import AuthForm from "@/components/AuthForm";

const Auth = () => {
  const { user, loading } = useAuth();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const inviteToken = searchParams.get("invite");

  const acceptInvite = useCallback(async (token: string) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.access_token) return;

      const res = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/accept-team-invite`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${session.access_token}`,
            "apikey": import.meta.env.VITE_SUPABASE_ANON_KEY,
          },
          body: JSON.stringify({ token }),
        }
      );

      const json = await res.json();
      if (res.ok && json.success) {
        toast.success(`Joined team: ${json.team_name ?? "Team"}`);
        navigate("/team", { replace: true });
        return;
      }
    } catch {
      // Silently fail — user can accept invite manually later
    }
    navigate("/", { replace: true });
  }, [navigate]);

  useEffect(() => {
    if (!loading && user) {
      if (inviteToken) {
        acceptInvite(inviteToken);
      } else {
        navigate("/", { replace: true });
      }
    }
  }, [user, loading, navigate, inviteToken, acceptInvite]);

  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <Card className="w-full max-w-md shadow-lg border-border/50">
        <CardHeader className="text-center space-y-2">
          <div className="flex items-center justify-center gap-2 mb-2">
            <Zap className="h-7 w-7 text-primary" />
            <span className="text-xl font-bold text-foreground tracking-tight">Rankora</span>
          </div>
          <CardTitle className="text-2xl">
            {inviteToken ? "Join Your Team" : "Welcome"}
          </CardTitle>
          <CardDescription>
            {inviteToken
              ? "Sign in or create an account to accept the team invitation"
              : "Sign in to rank candidates instantly"}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <AuthForm onSuccess={() => {
            if (inviteToken) {
              acceptInvite(inviteToken);
            } else {
              navigate("/", { replace: true });
            }
          }} />
        </CardContent>
      </Card>
    </div>
  );
};

export default Auth;
